import asyncio
from collections.abc import Awaitable, Callable


async def run_tasks(
    tasks: list[Callable[[], Awaitable[None]]],
    max_concurrent: int,
) -> None:
    semaphore = asyncio.Semaphore(max_concurrent)

    async def _runner(task: Callable[[], Awaitable[None]]) -> None:
        async with semaphore:
            await task()

    running = [asyncio.create_task(_runner(t)) for t in tasks]
    try:
        await asyncio.gather(*running)
    finally:
        for t in running:
            if not t.done():
                t.cancel()
        for t in running:
            while not t.done():
                try:
                    await t
                except BaseException:
                    pass

