import asyncio

log = []

def make(name):
    async def child():
        try:
            await asyncio.sleep(5)
        except asyncio.CancelledError:
            log.append(f"{name}-caught")
            await asyncio.shield(asyncio.sleep(0.2))
            log.append(f"{name}-clean")
            raise
    return child

async def parent():
    cs = [asyncio.create_task(make(f"c{i}")()) for i in range(3)]
    try:
        await asyncio.gather(*cs)
    finally:
        for c in cs:
            if not c.done():
                c.cancel()
        for c in cs:
            while not c.done():
                try:
                    await c
                except BaseException as e:
                    log.append(f"parent-await-raised-{type(e).__name__}")

async def main():
    p = asyncio.create_task(parent())
    await asyncio.sleep(0.1)
    p.cancel()
    try:
        await p
    except asyncio.CancelledError:
        log.append("main-cancelled")

asyncio.run(main())
print(log)
